package com.nigson.experience.consent;

import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
import com.nigson.experience.platform.*;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.*;
import static org.assertj.core.api.Assertions.*;

class PhoneConsentPersistenceTest {
 static class MutableClock extends Clock {Instant time=Instant.now().truncatedTo(java.time.temporal.ChronoUnit.MICROS);public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId zone){return this;}public Instant instant(){return time;}void advance(long seconds){time=time.plusSeconds(seconds);}}
 JdbcTemplate jdbc;PhoneConsent service;PhoneSecrets secrets;MutableClock clock;PlatformStore store;AuditWriter audit;DataSourceTransactionManager manager;SimpleMeterRegistry metrics;ActorAssertion.Actor customer;boolean revoked;
 @BeforeEach void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null,"messaging native harness supplies actual PostgreSQL");if(!url.matches("jdbc:postgresql://127.0.0.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_DB_REQUIRED");jdbc=new JdbcTemplate(new DriverManagerDataSource(url+"?currentSchema=experience","nigson_experience_app","mock-experience-runtime"));manager=new DataSourceTransactionManager(jdbc.getDataSource());metrics=new SimpleMeterRegistry();clock=new MutableClock();store=new PlatformStore(jdbc,manager,clock,metrics);audit=new AuditWriter(jdbc,clock,metrics);byte[] hmac=new byte[32],aes=new byte[32];Arrays.fill(hmac,(byte)7);Arrays.fill(aes,(byte)9);secrets=new PhoneSecrets(1,hmac,"synthetic",Map.of("synthetic",aes));service=service(audit);customer=actor(UUID.randomUUID());}
 ActorAssertion.Actor actor(UUID party){return new ActorAssertion.Actor(party,"http://synthetic.invalid","synthetic-subject-"+party,null,Set.of("CUSTOMER"),Set.of(),null);}
 PhoneConsent service(AuditWriter writer){return new PhoneConsent(jdbc,store,writer,secrets,clock,manager,a->{assertThat(TransactionSynchronizationManager.isActualTransactionActive()).isFalse();if(revoked)throw new Problem.Failure(ProblemCode.ACCESS_DENIED);},Set.of("SYNTHETIC_POLICY_NOT_APPROVED"));}
 String phone(){return "+2348"+String.format(Locale.ROOT,"%09d",Math.floorMod(UUID.randomUUID().getLeastSignificantBits(),1_000_000_000L));}
 PhoneValues.Input input(String channel,String phone,Set<String> purposes){return new PhoneValues.Input(channel,phone,"SYNTHETIC_POLICY_NOT_APPROVED",purposes);}
 PhoneValues.Destination create(String channel,String phone,Set<String> purposes){return service.create(customer,input(channel,phone,purposes),UUID.randomUUID().toString(),UUID.randomUUID());}
 UUID proof(UUID destination){return jdbc.queryForObject("SELECT id FROM experience.destination_verification WHERE destination_id=? AND status='PENDING'",UUID.class,destination);}
 PrivateWorkload.Proof workload(){var route=PrivateWorkload.ROUTES.stream().filter(r->r.api().equals("API-187")).findFirst().orElseThrow();return new PrivateWorkload.Proof(route.client(),"synthetic-workload",route,null);}
 UUID job(UUID proof){return UUID.nameUUIDFromBytes(("contact-verification:"+proof).getBytes(java.nio.charset.StandardCharsets.US_ASCII));}
 PhoneValues.Context context(UUID destination){UUID proof=proof(destination);return service.context(workload(),proof,job(proof));}
 PhoneValues.Destination confirm(PhoneValues.Destination d){return service.confirm(customer,d.id(),d.version(),context(d.id()).code(),UUID.randomUUID().toString(),UUID.randomUUID());}
 @Test void proofGrantsOnlyRequestedChannelPurposeAndEventsContainNoPhoneOrCode(){String phone=phone();var d=create("SMS",phone,Set.of("ORDER_UPDATES"));assertThat(d.status()).isEqualTo("PENDING");assertThat(d.maskedAddress()).doesNotContain(phone);assertThat(service.eligible(customer.party(),"SMS","ORDER_UPDATES")).isFalse();var context=context(d.id());assertThat(context.phone()).isEqualTo(phone);assertThat(context.toString()).doesNotContain(phone,context.code());var stored=jdbc.queryForMap("SELECT address_ciphertext,destination_hash FROM experience.communication_destination WHERE id=?",d.id());assertThat(new String((byte[])stored.get("address_ciphertext"),java.nio.charset.StandardCharsets.US_ASCII)).doesNotContain(phone);assertThat(stored.get("destination_hash")).isEqualTo(secrets.fingerprint(phone));var active=confirm(d);assertThat(active.status()).isEqualTo("ACTIVE");assertThat(active.version()).isEqualTo(1);assertThat(service.eligible(customer.party(),"SMS","ORDER_UPDATES")).isTrue();assertThat(service.eligible(customer.party(),"SMS","MARKETING")).isFalse();assertThat(service.eligible(customer.party(),"WHATSAPP","ORDER_UPDATES")).isFalse();assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.destination_verification WHERE destination_id=? AND status='CONFIRMED' AND code_ciphertext IS NULL",Long.class,d.id())).isEqualTo(1);for(String event:jdbc.queryForList("SELECT payload::text FROM experience.outbox_event WHERE aggregate_id=?",String.class,d.id())){assertThat(event).doesNotContain(phone,context.code(),"code_hmac","ciphertext");EventCodec.decode(event);}assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.consent_event WHERE party_id=? AND granted",Long.class,customer.party())).isEqualTo(1);}
 @Test void concurrentCreateAndConfirmationIssueOneProofAndGrant()throws Exception{String phone=phone(),key=UUID.randomUUID().toString();var input=input("SMS",phone,Set.of("MARKETING"));try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var futures=new ArrayList<Future<PhoneValues.Destination>>();for(int n=0;n<12;n++){int i=n;futures.add(pool.submit(()->service.create(customer,input,key+"-"+i,UUID.randomUUID())));}var ids=new HashSet<UUID>();for(var future:futures)ids.add(future.get(15,TimeUnit.SECONDS).id());assertThat(ids).hasSize(1);UUID id=ids.iterator().next();assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.destination_verification WHERE destination_id=?",Long.class,id)).isEqualTo(1);String code=context(id).code(),confirmKey=UUID.randomUUID().toString();var confirmations=new ArrayList<Future<Boolean>>();for(int n=0;n<12;n++)confirmations.add(pool.submit(()->{try{return service.confirm(customer,id,0,code,confirmKey,UUID.randomUUID()).status().equals("ACTIVE");}catch(PlatformStore.Conflict inProgress){assertThat(inProgress.getMessage()).isEqualTo("IDEMPOTENCY_IN_PROGRESS");return false;}}));int acknowledged=0;for(var f:confirmations)if(f.get(15,TimeUnit.SECONDS))acknowledged++;assertThat(acknowledged).isPositive();assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.consent_event WHERE party_id=? AND granted",Long.class,customer.party())).isEqualTo(1);}}
 @Test void incorrectCodesCommitFiveAttemptsAndReplayDoesNotConsumeAnother(){var d=create("SMS",phone(),Set.of("MARKETING"));String good=context(d.id()).code(),wrong=good.equals("000000")?"111111":"000000";for(int i=0;i<5;i++){String key=UUID.randomUUID().toString();for(int replay=0;replay<2;replay++)assertThatThrownBy(()->service.confirm(customer,d.id(),0,wrong,key,UUID.randomUUID())).isInstanceOf(Problem.Failure.class);assertThat(jdbc.queryForObject("SELECT attempts FROM experience.destination_verification WHERE destination_id=?",Integer.class,d.id())).isEqualTo(i+1);}assertThat(jdbc.queryForObject("SELECT status FROM experience.destination_verification WHERE destination_id=?",String.class,d.id())).isEqualTo("LOCKED");assertThat(jdbc.queryForObject("SELECT code_ciphertext FROM experience.destination_verification WHERE destination_id=?",byte[].class,d.id())).isNull();assertThatThrownBy(()->service.confirm(customer,d.id(),0,good,UUID.randomUUID().toString(),UUID.randomUUID())).isInstanceOf(Problem.Failure.class);assertThat(service.eligible(customer.party(),"SMS","MARKETING")).isFalse();}
 @Test void exactExpiryErasesCodeAndFreshRequestsAreLimitedWithoutChangingDestination(){String phone=phone();var d=create("WHATSAPP",phone,Set.of("ORDER_UPDATES"));UUID originalProof=proof(d.id());clock.advance(600);assertThatThrownBy(()->service.context(workload(),originalProof,job(originalProof))).isInstanceOf(Problem.Failure.class);assertThat(jdbc.queryForObject("SELECT code_ciphertext FROM experience.destination_verification WHERE id=?",byte[].class,originalProof)).isNull();for(int n=0;n<2;n++){assertThat(create("WHATSAPP",phone,Set.of("ORDER_UPDATES")).id()).isEqualTo(d.id());clock.advance(601);assertThat(service.expire(100)).isPositive();}assertThatThrownBy(()->create("WHATSAPP",phone,Set.of("ORDER_UPDATES"))).isInstanceOf(Problem.Failure.class);assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.destination_verification WHERE destination_id=?",Long.class,d.id())).isEqualTo(3);clock.advance(3601);assertThat(create("WHATSAPP",phone,Set.of("ORDER_UPDATES")).id()).isEqualTo(d.id());}
 @Test void privateContextRequiresOriginalDeterministicJobAndExactWorkload(){var d=create("SMS",phone(),Set.of("ORDER_UPDATES"));UUID proof=proof(d.id());assertThat(service.context(workload(),proof,job(proof)).code()).isEqualTo(context(d.id()).code());assertThatThrownBy(()->service.context(workload(),proof,UUID.randomUUID())).isInstanceOf(Problem.Failure.class);assertThatThrownBy(()->service.context(new PrivateWorkload.Proof("nigson-commerce","synthetic",workload().route(),null),proof,job(proof))).isInstanceOf(Problem.Failure.class);assertThatThrownBy(()->service.context(new PrivateWorkload.Proof(workload().client(),"synthetic",workload().route(),customer),proof,job(proof))).isInstanceOf(Problem.Failure.class);}
 @Test void withdrawalOverridesGrantsAndCachedConfirmation(){var d=create("SMS",phone(),Set.of("ORDER_UPDATES","MARKETING"));String code=context(d.id()).code(),key=UUID.randomUUID().toString();var active=service.confirm(customer,d.id(),0,code,key,UUID.randomUUID());service.withdraw(customer,d.id(),active.version(),UUID.randomUUID().toString(),UUID.randomUUID());assertThat(service.eligible(customer.party(),"SMS","ORDER_UPDATES")).isFalse();assertThat(service.eligible(customer.party(),"SMS","MARKETING")).isFalse();assertThatThrownBy(()->service.confirm(customer,d.id(),0,code,key,UUID.randomUUID())).isInstanceOf(Problem.Failure.class);assertThat(service.list(customer)).extracting(PhoneValues.Destination::status).containsExactly("UNSUBSCRIBED");assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.consent_event WHERE party_id=? AND NOT granted",Long.class,customer.party())).isEqualTo(2);}
 @Test void secondActiveDestinationRequiresExplicitWithdrawal(){var a=create("SMS",phone(),Set.of("MARKETING"));var b=create("SMS",phone(),Set.of("MARKETING"));var active=confirm(a);String bCode=context(b.id()).code();assertThatThrownBy(()->service.confirm(customer,b.id(),0,bCode,UUID.randomUUID().toString(),UUID.randomUUID())).isInstanceOf(Problem.Failure.class);service.withdraw(customer,a.id(),active.version(),UUID.randomUUID().toString(),UUID.randomUUID());assertThat(confirm(b).status()).isEqualTo("ACTIVE");}
 @Test void suppressionProtectsOtherPartiesButDoesNotGrantAnotherChannel(){String phone=phone();var d=create("SMS",phone,Set.of("MARKETING"));var other=actor(UUID.randomUUID());service.create(other,input("SMS",phone,Set.of("MARKETING")),UUID.randomUUID().toString(),UUID.randomUUID());service.withdraw(customer,d.id(),0,UUID.randomUUID().toString(),UUID.randomUUID());assertThatThrownBy(()->service.create(other,input("SMS",phone,Set.of("MARKETING")),UUID.randomUUID().toString(),UUID.randomUUID())).isInstanceOf(Problem.Failure.class);assertThat(create("WHATSAPP",phone,Set.of("MARKETING")).status()).isEqualTo("PENDING");}
 @Test void ownershipVersionAndCurrentAuthorityProtectReplay(){String phone=phone(),key=UUID.randomUUID().toString();var input=input("SMS",phone,Set.of("MARKETING"));var d=service.create(customer,input,key,UUID.randomUUID());assertThatThrownBy(()->service.withdraw(actor(UUID.randomUUID()),d.id(),0,"outsider",UUID.randomUUID())).isInstanceOf(Problem.Failure.class);assertThatThrownBy(()->service.withdraw(customer,d.id(),1,"stale",UUID.randomUUID())).isInstanceOf(Problem.Failure.class);assertThatThrownBy(()->service.create(customer,input("SMS",phone,Set.of("ORDER_UPDATES")),key,UUID.randomUUID())).isInstanceOf(PlatformStore.Conflict.class);revoked=true;assertThatThrownBy(()->service.create(customer,input,key,UUID.randomUUID())).isInstanceOf(Problem.Failure.class);assertThatThrownBy(()->service.list(customer)).isInstanceOf(Problem.Failure.class);}
 @Test void auditFailureRollsBackDestinationProofAndOutbox(){var failing=new JdbcTemplate(jdbc.getDataSource()){@Override public int update(String sql,Object... args){throw new org.springframework.dao.PermissionDeniedDataAccessException("SYNTHETIC_AUDIT_DENIAL",null);}};var failed=service(new AuditWriter(failing,clock,metrics));assertThatThrownBy(()->failed.create(customer,input("SMS",phone(),Set.of("MARKETING")),UUID.randomUUID().toString(),UUID.randomUUID())).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.communication_destination WHERE party_id=?",Long.class,customer.party())).isZero();assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.destination_verification WHERE created_by=?",Long.class,customer.party().toString())).isZero();}
 PrivateWorkload.Proof serviceProof(String api){var route=PrivateWorkload.ROUTES.stream().filter(r->r.api().equals(api)).findFirst().orElseThrow();return new PrivateWorkload.Proof(route.client(),"synthetic-workload",route,null);}
 @Test void onlyConfiguredPolicyVersionsCanIssueOrActivateProofs(){assertThatThrownBy(()->service.create(customer,new PhoneValues.Input("SMS",phone(),"UNAPPROVED_CLIENT_POLICY",Set.of("MARKETING")),"policy",UUID.randomUUID())).isInstanceOf(Problem.Failure.class);assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.communication_destination WHERE party_id=?",Long.class,customer.party())).isZero();}
 @Test void privateEligibilityProvidesPhoneOnlyForCurrentRequestedPurposeAndSuppressionWins(){String phone=phone();var d=confirm(create("SMS",phone,Set.of("ORDER_UPDATES")));var input=new PhoneValues.EligibilityInput(customer.party(),d.id(),"SMS","ORDER_UPDATES");var granted=service.eligibility(serviceProof("API-127"),input);assertThat(granted.eligible()).isTrue();assertThat(granted.phone()).isEqualTo(phone);assertThat(granted.email()).isNull();assertThat(granted.toString()).doesNotContain(phone);var denied=service.eligibility(serviceProof("API-127"),new PhoneValues.EligibilityInput(customer.party(),null,"SMS","MARKETING"));assertThat(denied.eligible()).isFalse();assertThat(denied.phone()).isNull();assertThatThrownBy(()->service.eligibility(workload(),input)).isInstanceOf(Problem.Failure.class);assertThatThrownBy(()->service.eligibility(serviceProof("API-127"),new PhoneValues.EligibilityInput(UUID.randomUUID(),d.id(),"SMS","ORDER_UPDATES"))).isInstanceOf(Problem.Failure.class);UUID command=UUID.randomUUID();var signal=new PhoneValues.Signal(command,secrets.fingerprint(phone),"SMS","OPT_OUT");assertThat(service.suppress(serviceProof("API-175"),signal,UUID.randomUUID())).isTrue();assertThat(service.suppress(serviceProof("API-175"),signal,UUID.randomUUID())).isTrue();var after=service.eligibility(serviceProof("API-127"),input);assertThat(after.eligible()).isFalse();assertThat(after.phone()).isNull();assertThat(after.reasonCode()).isEqualTo("SUPPRESSED");assertThat(service.list(customer).getFirst().status()).isEqualTo("SUPPRESSED");assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.communication_suppression WHERE destination_hash=? AND channel='SMS'",Long.class,secrets.fingerprint(phone))).isEqualTo(1);assertThatThrownBy(()->service.suppress(serviceProof("API-127"),signal,UUID.randomUUID())).isInstanceOf(Problem.Failure.class);assertThatThrownBy(()->service.suppress(serviceProof("API-175"),new PhoneValues.Signal(command,secrets.fingerprint(phone),"SMS","COMPLAINT"),UUID.randomUUID())).isInstanceOf(PlatformStore.Conflict.class);}
 @Test void suppressionAuditFailureCannotAcknowledgeAnUncommittedSuppression(){var failing=new JdbcTemplate(jdbc.getDataSource()){@Override public int update(String sql,Object... args){throw new org.springframework.dao.PermissionDeniedDataAccessException("SYNTHETIC_AUDIT_DENIAL",null);}};var failed=service(new AuditWriter(failing,clock,metrics));String hash=secrets.fingerprint(phone());assertThatThrownBy(()->failed.suppress(serviceProof("API-175"),new PhoneValues.Signal(UUID.randomUUID(),hash,"WHATSAPP","OPT_OUT"),UUID.randomUUID())).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.communication_suppression WHERE destination_hash=?",Long.class,hash)).isZero();}
}
